arguments.command:
cat > /tmp/stackalloc_nint/Program.cs << 'EOF'
Span<nint> span = stackalloc nint[4];
for (int i = 0; i < span.Length; i++)
    span[i] = (nint)(i * 10);

foreach (var val in span)
    Console.WriteLine(val);

Console.WriteLine($"nint size: {nint.Size} bytes");
EOF
